{\begin{equation*}
\beta_{L_V}(h) =  \beta_{L}(h) \quad \Longleftrightarrow\quad
{ \mathfrak M}_{L}^h \subseteq  { \mathfrak M}_{L_V}^h 
\;\; \text{and} \;\;
V \equiv 0 \;\; \text{on}  \;\; \widetilde { \mathcal M}_{L}^h \subseteq \widetilde { \mathcal M}_{L_V}^h.
