\begin{theorem}[Bangert]\label{thm_bangert}
	Suppose a Riemannian metric $g$ on the $2$-torus $\T^2$ has the same stable norm or Mather's $\beta$-function as a flat metric $g_0$ on $\T^2$. Then, $(\T^2, g)$ and $(\T^2, g_0)$ are isometric by an isometry homotopic to the identity.
\end{theorem}

