\label{main thm 1-free}
For a subgroup $H$ of $F_n\times\mathbb{Z}^m (n, m\geq 2)$, the following items are equivalent:

\begin{enumerate}
    \item $H$ is aut-fixed up to isomorphism;
    \item $H$ is end-fixed up to isomorphism;
    \item $H$ is not isomorphic to $F_{\aleph_0}, ~F_t\times \mathbb{Z}^m(t> n)$;
    \item $H$ is isomorphic to one of the following groups: $$F_t \times \mathbb Z^m(0 \leq t \leq n), ~F_t \times \mathbb Z^s(t \geq 0, 0 \leq s \leq m-1), ~F_{\aleph_0} \times \mathbb Z^s(1\leq s\leq m).$$
\end{enumerate}

