\begin{thm}\label{main thm 2-surf}
For a subgroup $H$ of $\pi_1(\Sigma_g)\times\mathbb{Z}^m  (g, m\geq 2)$, the following items are equivalent:
\begin{enumerate}
    \item $H$ is aut-fixed up to isomorphism;
    \item $H$ is end-fixed up to isomorphism;
    \item $H$ is not isomorphic to $F_{\aleph_0},  ~F_t\times \mathbb{Z}^m (t \geq 2g), ~\pi_1(\Sigma_k)\times\mathbb{Z}^m (k > g)$;
    \item $H$ is isomorphic to one of the following groups: $$F_t \times \Z^s(t \geq 0, 0 \leq s \leq m-1), ~F_t \times \Z^m(0\leq t <2g), ~F_{\aleph_0} \times \Z^s(1\leq s\leq m),$$
    $$~\pi_1(\Sigma_{k(g-1)+1})\times \Z^s(k \geq 1, 0\leq s \leq m-1), ~\pi_1(\Sigma_g)\times \Z^m.$$
\end{enumerate}
\end{thm}

post_theorem_intro_text:
\begin{thm}\label{main thm 2-surf}
For a subgroup $H$ of $\pi_1(\Sigma_g)\times\mathbb{Z}^m  (g, m\geq 2)$, the following items are equivalent:
\begin{enumerate}
    \item $H$ is aut-fixed up to isomorphism;
    \item $H$ is end-fixed up to isomorphism;
    \item $H$ is not isomorphic to $F_{\aleph_0},  ~F_t\times \mathbb{Z}^m (t \geq 2g), ~\pi_1(\Sigma_k)\times\mathbb{Z}^m (k > g)$;
    \item $H$ is isomorphic to one of the following groups: $$F_t \times \mathbb Z^s(t \geq 0, 0 \leq s \leq m-1), ~F_t \times \mathbb Z^m(0\leq t <2g), ~F_{\aleph_0} \times \mathbb Z^s(1\leq s\leq m),$$
    $$~\pi_1(\Sigma_{k(g-1)+1})\times \mathbb Z^s(k \geq 1, 0\leq s \leq m-1), ~\pi_1(\Sigma_g)\times \mathbb Z^m.$$
\end{enumerate}
\end{thm}

Note that the above Item (1), Item (3) and Item (4) have been proven to be equivalent in \cite{LWZ25}, and Item (1) implies Item (2) clearly, we only need to prove that Item (2) implies Item (3).
When $m=1$, both of $\pi_1(\Sigma_g)\times\mathbb Z$ and $F_n\times\mathbb Z$ contain, up to isomorphism, only finitely many fixed subgroups of automorphisms, see \cite[Theorem 4.3, Theorem 5.3]{LWZ25}. In contrast, they contain infinitely many fixed subgroups of endomorphisms. More precisely, we have the following.

\begin{thm}\label{main thm 3-Z free}
Let $H$ be a subgroup  of $F_n\times\mathbb Z(n \geq 2)$. Then

 (1) $H$ is aut-fixed up to isomorphism if and only if $H$ is not isomorphic to
 $$F_{\aleph_0}, ~F_t\times\mathbb Z(t>n); \quad F_{2k} (2k> n ), ~F_t(t>2n).$$

 (2) $H$ is end-fixed up to isomorphism if and only if $H$ is not isomorphic to
 $$ F_{\aleph_0}, ~F_t\times\mathbb Z(t>n).$$
\end{thm}

\begin{thm}\label{main thm 4-Z surf}
 Let $H$ be a subgroup  of $\pi_1(\Sigma_g)\times\mathbb Z(g \geq 2)$. Then

 (1) $H$ is aut-fixed up to isomorphism if and only if $H$ is not isomorphic to
 $$F_{\aleph_0},  ~F_t\times\mathbb Z(t \geq 2g), ~\pi_1(\Sigma_k)\times\mathbb Z(k > g);$$
 $$F_{2n} (n\geq g ), ~F_t(t \geq 4g-1), ~~\pi_1(\Sigma_k)(2g-1\neq k>g).$$

 (2) $H$ is end-fixed up to isomorphism if and only if $H$ is not isomorphic to
$$ F_{\aleph_0},  ~F_t\times\mathbb Z(t \geq 2g), ~\pi_1(\Sigma_k)\times\mathbb Z(k > g). $$
\end{thm}

Recall that free-abelian groups $\mathbb Z^n$ and free groups $F_n(n\geq 1)$ are Hopfian (i.e. every epimorphism is an automorphism) but not co-Hopfian (i.e. every monomorphism is an automorphism) since they contain proper subgroups isomorphic to themselves; every closed surface group  $\pi_1(\Sigma_g)(g\geq 2)$ is both Hopfian and co-Hopfian \cite{Ba62,DVa97,Fr63,He72,Ho31}. Now, we show that free-abelian times surface groups are Hopfian through the residually finiteness of surface groups, and show they are not co-Hopfian by constructing isomorphic proper subgroups.

\begin{cor}\label{Hopf cor}
Let $G=H\times\mathbb{Z}^m (m\geq 1)$ for $H=F_g$ or $H=\pi_1(\Sigma_g)$ $(g\geq 1)$. Then $G$ is Hopfian but not co-Hopfian.	
\end{cor}

Moreover, this result can be generalized to all (Gromov) hyperbolic groups. However, since the question of whether hyperbolic groups are always residually finite remains open, we cannot directly deduce this conclusion from the residually finiteness. In fact, it can be derived from the Hopfian property of hyperbolic groups \cite{FS23} and a corollary in \cite{Hi69}.

\begin{cor}\label{Hopf cor for hyperbolic case}
    Let $G=H\times\mathbb{Z}^m (m\geq 1)$ for $H$ a hyperbolic group. Then, $G$ is Hopfian but not co-Hopfian.
\end{cor}

For every non-elementary torsion-free hyperbolic group $H$, Lei, Wang and Zhang \cite[Theorem 1.6]{LWZ25} provided an equivalent condition for $H\times \mathbb Z^k (k \geq2)$ to contain, up to isomorphism, infinitely many aut-fixed subgroups. We adapt their result concerning the aut-fixed subgroups of $H\times \mathbb Z^k (k\geq 2)$ into the following theorem about the end-fixed subgroups of $H\times\mathbb Z^k (k\geq 1)$ through a similar argument.

\begin{thm}\label{thm hyper. times Z^m finite end-fixed subgps}
    Let $H$ be a non-elementary torsion-free hyperbolic group, and let $\beta_1(H)$ be its first betti number. Then $H\times\mathbb Z^k\ (k\geq 1)$ contains, up to isomorphism, finitely many fixed subgroups of endomorphisms if and only if $\beta_1(H)=0$ and $H$ contains, up to isomorphism, finitely many fixed subgroups of endomorphisms.
\end{thm}

\begin{rem}
    Shor \cite{Sh99} showed every hyperbolic group contains, up to isomorphism, only finitely many aut-fixed subgroups. Lei and Zhang \cite{LZ23} extended this result and showed every hyperbolic group contains, up to isomorphism, only finitely many fixed subgroups of monomorphisms. However, the question of whether the same result holds for endomorphisms remains open.
\end{rem}

The paper is organized as follows. In Section \ref{sect 2}, we introduce some important facts on subgroups of $F_n\times \mathbb Z^m$ and $\pi_1(\Sigma_g)\times \mathbb Z^m$. In Section \ref{sect 3}, we prove the main results for end-fixed subgroups in $F_n\times \mathbb Z^m$. In Section \ref{sect 4}, we first study endomorphisms of $\pi_1(\Sigma_g)\times \mathbb Z^m$, and then prove Theorem \ref{main thm 2-surf} and Theorem \ref{main thm 4-Z surf}. Finally, in Section \ref{sect 5}, we obtain some results about the endomorphisms of free-abelian times hyperbolic groups.

